#include <iostream>

int tran(int a, int b) {
    int t;
    int res = 0;
    int pow = 1;
    do {
        t = a / b;
        res += pow * (a - (a / b) * b);
        a = t;
        pow *= 10;
    } while (t >= b);
    res += pow * t;
    return res;
}

int main() {
    int b;
    std::cin >> b;

    for (int i = 1; i < b; ++i) {
        for (int j = 1; j < b; ++j) {
            std::cout << tran(i * j, b) << ' ';
        }
        std::cout << '\n';
    }

    return 0;
}

